#define MAX_LEN 7
#define MAX_CHARS 10

// Global variables for backtracking
char chars[26];       // which chars are used
int charCount;        // number of unique chars
int charToDigit[26];  // mapping from char to digit
bool usedDigit[10];   // which digits are used
int wordsCount;
char words[MAX_WORDS][MAX_LEN + 1];
char result[MAX_LEN + 1];

