// We'll do column-wise addition with carry
// For each position, we have an array of indices of chars in words that appear at that position
// and one char index for result at that position (or -1 if none)
int posWordsChars[MAX_LEN][MAX_WORDS]; // store char indices for each word at position
int posWordsCount[MAX_LEN];             // how many words have char at that position
int posResultChar[MAX_LEN];             // char index for result at that position or -1

// Backtracking function to assign digits to chars
