    if (idx == maxLen) {
        // At the end, carry must be zero
        return carry == 0;
    }

    // Sum of digits at this position from words plus carry
    int sum = carry;

    // For each word char at this position, add its digit if assigned, else try all digits
    // But we do this in a single step by trying digits for unassigned chars

    // We will try to assign digits to unassigned chars at this position in words first,
    // then check the result char digit.

    // Collect all chars at this position (words + result)
    // For words chars, sum their digits
    // For result char, check if digit matches sum % 10

    // We will try all possible assignments for unassigned chars at this position (words and result)
    // but only for those chars that are unassigned.

    // To do this efficiently, we try to assign digits to unassigned chars in order.

    // First, collect all chars at this position (words and result)
    // We will assign digits to unassigned chars in order.

    // We'll create an array of chars to assign at this position
    // and try all digit assignments for them.

    // But since at most 10 chars total, and at most 6 chars per position (5 words + 1 result),
    // we can do a DFS here.

    // To simplify, we do a recursive helper function here.

    // Helper function for assigning digits to chars at this position
    // idx2: index of char to assign at this position
    // sumSoFar: sum of digits assigned so far (words only)
    // charsToAssign: array of char indices to assign
    // charsToAssignCount: number of chars to assign
    // resultChar: char index of result at this position (-1 if none)
    // returns true if assignment leads to a solution

    int wordsCharCount = posWordsCount[idx];
    int charsToAssign[MAX_WORDS + 1];
    int charsToAssignCount = 0;

    // For words chars at this position
    for (int i = 0; i < wordsCharCount; i++) {
        int c = posWordsChars[idx][i];
        if (charToDigit[c] == -1) {
            // unassigned char
            charsToAssign[charsToAssignCount++] = c;
        }
    }

    int resChar = posResultChar[idx];
    bool resCharAssigned = (resChar == -1) ? true : (charToDigit[resChar] != -1);
    if (!resCharAssigned) {
        charsToAssign[charsToAssignCount++] = resChar;
    }

