    bool helper(int idx2, int sumSoFar) {
        if (idx2 == charsToAssignCount) {
            // All chars assigned at this position
            // sumSoFar is sum of digits of words chars at this position
            // result digit must be sumSoFar % 10
            int expectedDigit = sumSoFar % 10;
            int carryNext = sumSoFar / 10;

            if (resChar == -1) {
                // no result char at this position, sumSoFar must be 0 mod 10
                if (expectedDigit != 0) return false;
                return backtrack(idx + 1, carryNext);
            } else {
                int d = charToDigit[resChar];
                if (d != expectedDigit) return false;
                return backtrack(idx + 1, carryNext);
            }
        }

        int c = charsToAssign[idx2];

        // If c is result char
        bool isResultChar = (c == resChar);

        // Try all digits 0-9 not used
        for (int d = 0; d <= 9; d++) {
            if (usedDigit[d]) continue;
            if (d == 0 && cannotBeZero[c]) continue;

            charToDigit[c] = d;
            usedDigit[d] = true;

            int newSumSoFar = sumSoFar;
            // If c is a word char, add digit to sumSoFar
            // If c is result char, do not add to sumSoFar
            bool isWordChar = false;
            for (int i = 0; i < wordsCharCount; i++) {
                if (posWordsChars[idx][i] == c) {
                    isWordChar = true;
                    break;
                }
            }
            if (isWordChar) newSumSoFar += d;

            if (helper(idx2 + 1, newSumSoFar)) {
                return true;
            }

            charToDigit[c] = -1;
            usedDigit[d] = false;
        }
        return false;
    }

    // sumSoFar from assigned digits of words chars at this position
    int sumSoFar = 0;
    for (int i = 0; i < wordsCharCount; i++) {
        int c = posWordsChars[idx][i];
        if (charToDigit[c] != -1) {
            sumSoFar += charToDigit[c];
        }
    }

    return helper(0, sumSoFar);
}

bool isSolvable(char **wordsInput, int wordsSize, char *resultInput) {
    wordsCount = wordsSize;
    // Copy words and result to global arrays
    for (int i = 0; i < wordsCount; i++) {
        strcpy(words[i], wordsInput[i]);
    }
    strcpy(result, resultInput);

    // Initialize
    memset(charToDigit, -1, sizeof(charToDigit));
    memset(usedDigit, 0, sizeof(usedDigit));
    memset(cannotBeZero, 0, sizeof(cannotBeZero));
    charCount = 0;

    // Collect unique chars
    bool used[26] = {0};
    for (int i = 0; i < wordsCount; i++) {
        int len = (int)strlen(words[i]);
        wordLen[i] = len;
        for (int j = 0; j < len; j++) {
            int c = words[i][j] - 'A';
            if (!used[c]) {
                used[c] = true;
                chars[charCount++] = c;
            }
        }
    }
    int lenR = (int)strlen(result);
    resultLen = lenR;
    for (int j = 0; j < lenR; j++) {
        int c = result[j] - 'A';
        if (!used[c]) {
            used[c] = true;
            chars[charCount++] = c;
        }
    }

    if (charCount > 10) return false; // more than 10 unique chars, impossible

    // Mark chars that cannot be zero (leading chars)
    for (int i = 0; i < wordsCount; i++) {
        int c = words[i][0] - 'A';
        cannotBeZero[c] = true;
    }
    cannotBeZero[result[0] - 'A'] = true;

    // Map char to index in chars array for quick lookup
    int charIndexMap[26];
    for (int i = 0; i < 26; i++) charIndexMap[i] = -1;
    for (int i = 0; i < charCount; i++) {
        charIndexMap[chars[i]] = i;
    }

    // Rebuild words and result as arrays of indices in chars
    // We'll store them reversed for easier addition from right to left
    // Also find maxLen = max length of words and result
    maxLen = 0;
    for (int i = 0; i < wordsCount; i++) {
        int len = wordLen[i];
        if (len > maxLen) maxLen = len;
        // reverse and map
        for (int j = 0; j < len; j++) {
            words[i][j] = (char)charIndexMap[words[i][len - 1 - j] - 'A'];
        }
        words[i][len] = -1; // mark end
    }
    if (resultLen > maxLen) maxLen = resultLen;
    for (int j = 0; j < resultLen; j++) {
        result[j] = (char)charIndexMap[result[resultLen - 1 - j] - 'A'];
    }
    result[resultLen] = -1;

    // For each position, collect chars in words and result
    for (int pos = 0; pos < maxLen; pos++) {
        posWordsCount[pos] = 0;
        for (int w = 0; w < wordsCount; w++) {
            if (pos < wordLen[w]) {
                posWordsChars[pos][posWordsCount[pos]++] = words[w][pos];
            }
        }
        if (pos < resultLen) {
            posResultChar[pos] = result[pos];
        } else {
            posResultChar[pos] = -1;
        }
    }

    // Initialize charToDigit to -1
    for (int i = 0; i < charCount; i++) {
        charToDigit[i] = -1;
    }

    // Start backtracking from position 0 with carry 0
    return backtrack(0, 0);
}

// LeetCode function signature
bool isSolvable(char **words, int wordsSize, char *result);

